import { promises as fs } from "fs";
import path from "path";

const DATA_FILE = path.join(process.cwd(), "data", "books.json");

async function ensureFile() {
  await fs.mkdir(path.dirname(DATA_FILE), { recursive: true });
  try {
    await fs.access(DATA_FILE);
  } catch {
    await fs.writeFile(DATA_FILE, "[]\n", "utf8");
  }
}

export async function getBooks() {
  await ensureFile();
  const raw = await fs.readFile(DATA_FILE, "utf8");
  return JSON.parse(raw);
}

export async function getBook(id) {
  const books = await getBooks();
  return books.find((b) => b.id === id) || null;
}

async function saveBooks(books) {
  await ensureFile();
  await fs.writeFile(DATA_FILE, JSON.stringify(books, null, 2) + "\n", "utf8");
}

export async function addBook({ title, author, notes }) {
  const books = await getBooks();
  const book = {
    id: crypto.randomUUID(),
    title,
    author,
    notes: notes || "",
    status: "reading",
    createdAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.push(book);
  await saveBooks(books);
  return book;
}

export async function finishBook(id) {
  const books = await getBooks();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.status = "finished";
  book.finishedAt = new Date().toISOString();
  await saveBooks(books);
  return book;
}

export async function updateNotes(id, notes) {
  const books = await getBooks();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.notes = notes;
  await saveBooks(books);
  return book;
}

