"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { addBook, finishBook, updateNotes } from "../lib/books";

export async function addBookAction(formData) {
  const title = String(formData.get("title") || "").trim();
  const author = String(formData.get("author") || "").trim();
  const notes = String(formData.get("notes") || "").trim();
  if (!title || !author) return;
  const book = await addBook({ title, author, notes });
  revalidatePath("/");
  redirect(`/books/${book.id}`);
}

export async function finishBookAction(formData) {
  const id = String(formData.get("id") || "");
  if (!id) return;
  await finishBook(id);
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
}

export async function saveNotesAction(formData) {
  const id = String(formData.get("id") || "");
  if (!id) return;
  await updateNotes(id, String(formData.get("notes") || ""));
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
}

