* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, sans-serif;
  color: #1a1a1a;
  background: #fafafa;
}

.container {
  max-width: 40rem;
  margin: 0 auto;
  padding: 2rem 1rem;
}

h1 {
  margin-bottom: 1.5rem;
}

h2 {
  margin-top: 2rem;
  border-bottom: 1px solid #ddd;
  padding-bottom: 0.25rem;
}

.book-list {
  list-style: none;
  padding: 0;
  margin: 1rem 0;
}

.book-list li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  padding: 0.5rem 0;
  border-bottom: 1px solid #eee;
}

.book-list a {
  color: #1a1a1a;
  font-weight: 600;
}

.author {
  color: #666;
}

form.add-book,
form.notes {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-top: 1rem;
}

input,
textarea {
  padding: 0.5rem;
  border: 1px solid #ccc;
  border-radius: 4px;
  font: inherit;
  width: 100%;
}

button {
  padding: 0.5rem 1rem;
  border: none;
  border-radius: 4px;
  background: #1a1a1a;
  color: #fff;
  font: inherit;
  cursor: pointer;
  align-self: flex-start;
}

button.subtle {
  background: #e5e5e5;
  color: #1a1a1a;
}

.meta {
  color: #666;
  font-size: 0.9rem;
}

.empty {
  color: #888;
}

