import Link from "next/link";
import { getBooks } from "../lib/books";
import { addBookAction, finishBookAction } from "./actions";

export const dynamic = "force-dynamic";

function BookRow({ book, showFinish }) {
  return (
    <li>
      <span>
        <Link href={`/books/${book.id}`}>{book.title}</Link>{" "}
        <span className="author">by {book.author}</span>
      </span>
      {showFinish && (
        <form action={finishBookAction}>
          <input type="hidden" name="id" value={book.id} />
          <button type="submit" className="subtle">
            Mark finished
          </button>
        </form>
      )}
    </li>
  );
}

export default async function Home() {
  const books = await getBooks();
  const reading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");

  return (
    <>
      <h1>My Books</h1>

      <h2>Currently reading</h2>
      {reading.length === 0 ? (
        <p className="empty">Nothing on the go right now.</p>
      ) : (
        <ul className="book-list">
          {reading.map((b) => (
            <BookRow key={b.id} book={b} showFinish />
          ))}
        </ul>
      )}

      <h2>Finished</h2>
      {finished.length === 0 ? (
        <p className="empty">No finished books yet.</p>
      ) : (
        <ul className="book-list">
          {finished.map((b) => (
            <BookRow key={b.id} book={b} />
          ))}
        </ul>
      )}

      <h2>Add a book</h2>
      <form action={addBookAction} className="add-book">
        <input name="title" placeholder="Title" required />
        <input name="author" placeholder="Author" required />
        <textarea name="notes" placeholder="Notes (optional)" rows={3} />
        <button type="submit">Add book</button>
      </form>
    </>
  );
}

